/// View over `expr`, the rule supplied by the operator table.
///
/// Exposes the flat operand/operator stream. Folding it by precedence is
/// the M3 driver's job; until then a language that needs expressions can
/// override `Handlers::expr` and walk this itself.
#[derive(Clone, Debug)]
pub struct ExprView<'i> {
    node: Node<'i, Rule>,
}

impl<'i> View<'i, Rule> for ExprView<'i> {
    fn from_pair(pair: Pair<'i, Rule>, file: FileId) -> Self {
        ExprView { node: Node::new(pair, file) }
    }

    fn node(&self) -> &Node<'i, Rule> {
        &self.node
    }
}

impl<'i> ExprView<'i> {
    /// Every direct child, operands and operators interleaved.
    pub fn parts(&self) -> Vec<Node<'i, Rule>> {
        self.node.children().collect()
    }

    /// The raw pairs the operator driver folds.
    pub fn pairs(&self) -> Vec<Pair<'i, Rule>> {
        self.node.pair().clone().into_inner().collect()
    }
}

